import re


def parse_requirements(text):
    result = []
    for line in text.splitlines():
        line = line.split("#", 1)[0].strip()
        if not line:
            continue
        match = re.match(r"^([A-Za-z0-9_.-]+)==([A-Za-z0-9_.-]+)$", line)
        if match:
            result.append((match.group(1), match.group(2)))
    return result
